.libPaths(c('work/stage5_Rlib',.libPaths()));library(susieR);library(coloc)
b<-read.csv('outputs/stage6_rbm6_gtex_direct_aligned.csv');d<-read.csv('outputs/stage6_rbm6_gtex_mvp_aligned.csv');n<-nrow(b);ix<-d$ld_row+1;stopifnot(all(ix>=1 & ix<=n),!anyDuplicated(ix),identical(as.character(b$rs[ix]),as.character(d$rs)));R<-matrix(readBin('work/stage6_rbm6_gtex_direct_nfe_ld.bin','double',n=n*n,size=8,endian='little'),n,n)[ix,ix];dimnames(R)<-list(d$rs,d$rs);stopifnot(min(eigen(R,symmetric=TRUE,only.values=TRUE)$values)> -1e-8)
traits<-c('GTEx_cortex_RBM6','MVP_insomnia','Mak_FI','Ye_FFS');ns<-c(205,408138,402910,386565);fits<-list();diagnostics<-list();members<-list()
for(i in seq_along(traits)){t<-traits[i];z<-switch(t,GTEx_cortex_RBM6=d$beta/d$se,MVP_insomnia=d$mvp_z,Mak_FI=d$Mak_FI_beta/d$Mak_FI_se,Ye_FFS=d$Ye_FFS_beta/d$Ye_FFS_se);names(z)<-d$rs;lambda<-estimate_s_rss(z,R,n=ns[i]);set.seed(42);f<-susie_rss(z=z,R=R,n=ns[i],L=10,coverage=.95,estimate_residual_variance=FALSE,max_iter=500);fits[[t]]<-f;diagnostics[[i]]<-data.frame(trait=t,working_n=ns[i],n_variants=nrow(d),reference='NFE',lambda=lambda,converged=f$converged,iterations=f$niter,n_sets=length(f$sets$cs),max_pip=max(f$pip),top_variant_pip=f$pip[match('chr3_50085532_T_C',d$rs)]);if(length(f$sets$cs))for(k in seq_along(f$sets$cs)){j<-f$sets$cs[[k]];members[[length(members)+1]]<-data.frame(trait=t,component=f$sets$cs_index[k],variant=d$rs[j],pip=f$pip[j])};cat(t,'sets',length(f$sets$cs),'lambda',lambda,'converged',f$converged,'\n');flush.console()}
write.csv(do.call(rbind,diagnostics),'outputs/stage6_rbm6_gtex_mvp_totaln_diagnostics.csv',row.names=FALSE);if(length(members))write.csv(do.call(rbind,members),'outputs/stage6_rbm6_gtex_mvp_totaln_members.csv',row.names=FALSE);saveRDS(fits,'work/stage6_rbm6_gtex_mvp_totaln_susie_fits.rds');out<-list();pairs<-list(c(1,2),c(1,3),c(1,4),c(2,3),c(2,4));for(pair in pairs){a<-fits[[pair[1]]];g<-fits[[pair[2]]];if(!a$converged||!g$converged||!length(a$sets$cs)||!length(g$sets$cs))next;for(p12 in c(1e-6,1e-5,5e-5)){x<-as.data.frame(coloc.susie(a,g,p1=1e-4,p2=1e-4,p12=p12)$summary);x$trait1<-traits[pair[1]];x$trait2<-traits[pair[2]];x$p12<-p12;out[[length(out)+1]]<-x}};if(length(out))write.csv(do.call(rbind,out),'outputs/stage6_rbm6_gtex_mvp_totaln_coloc.csv',row.names=FALSE)
